(867,1623,$mw$8293A3BC7C0F29AB5A28AD1AFAB16946AE076391C96586B1D80162548630F300$mw$,$mw$24653c98c3e1b38dc620d29f91d2f84a$mw$,$mw$$mw$,$mw${"Id":1623,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"لإيجاد جذر $f(x)=x^2-2$ بطريقة التنصيف على الفترة [1,2]، ما أول نقطة وسطية؟","TitleEn":"Using bisection to find a zero of $f(x)=x^2-2$ on [1,2], what is the first midpoint?","QuestionTextAr":"لإيجاد جذر $f(x)=x^2-2$ بطريقة التنصيف على الفترة [1,2]، ما أول نقطة وسطية؟","QuestionTextEn":"Using bisection to find a zero of $f(x)=x^2-2$ on [1,2], what is the first midpoint?","DetailedSolutionAr":"القانون المستخدم: طريقة التنصيف تبدأ بفترة تحصر جذراً، وتحسب منتصفها m = (a+b)/2. للفترة [1،2] نحسب m = (1 + 2)/2 = 1.5. لأن f(1) = −1 وf(2) = 2 تتبدل الإشارة بين الطرفين، فيناسب استعمال التنصيف ثم اختبار f(1.5) لتحديد النصف التالي.","DetailedSolutionEn":"Rule used: Bisection uses a bracket [a,b] and first tests its midpoint m = (a+b)/2. For [1,2], m = (1+2)/2 = 1.5. Here f(1) = −1 and f(2) = 2 have opposite signs, so the bracket is valid and the next step evaluates f(1.5).","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6481,"Order":1,"LatexCode":"1","IsCorrect":false},{"Id":6482,"Order":2,"LatexCode":"1.25","IsCorrect":false},{"Id":6483,"Order":3,"LatexCode":"1.5","IsCorrect":true},{"Id":6484,"Order":4,"LatexCode":"2","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"طريقة التنصيف تبدأ من منتصف المجال المعطى.","En":"Bisection begins at the midpoint of the given interval."},{"Ar":"اجمع طرفي المجال واقسم على اثنين؛ ويمكن فحص قيمة الدالة عند المنتصف.","En":"Average the endpoints; evaluate the function there if needed."}],"Title":{"Ar":"لإيجاد جذر $f(x)=x^2-2$ بطريقة التنصيف على الفترة [1,2]، ما أول نقطة وسطية؟","En":"Using bisection to find a zero of $f(x)=x^2-2$ on [1,2], what is the first midpoint?"},"Points":10,"Options":[{"LatexCode":"1","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1 هو الطرف الأيسر لا المنتصف.","En":"One is the left endpoint, not the midpoint."}},{"LatexCode":"1.25","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1.25 قد يظهر في خطوة لاحقة بعد تضييق الفترة.","En":"1.25 may occur in a later step after narrowing the bracket."}},{"LatexCode":"1.5","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"2","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"2 هو الطرف الأيمن.","En":"Two is the right endpoint."}}],"StageId":4,"Question":{"Ar":"لإيجاد جذر $f(x)=x^2-2$ بطريقة التنصيف على الفترة [1,2]، ما أول نقطة وسطية؟","En":"Using bisection to find a zero of $f(x)=x^2-2$ on [1,2], what is the first midpoint?"},"Solution":{"Idea":{"Ar":"طريقة التنصيف: منتصف فترة تحصر جذراً.","En":"Bisection: midpoint of a root bracket."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"الدالة مستمرة على الفترة وإشارتا قيمتي الطرفين مختلفتان، لذا تحصر جذراً.","En":"The function is continuous and endpoint values have opposite signs, so the interval brackets a root."},{"Ar":"$f(1)=-1,\\quad f(2)=2$","En":"$f(1)=-1,\\quad f(2)=2$"},{"Ar":"أول خطوة هي حساب متوسط الطرفين، وليس حل المعادلة بدقة.","En":"The first step averages the endpoints rather than solving exactly."}],"Result":{"Ar":"$1.5$","En":"$1.5$"},"CommonError":{"Ar":"لا تخلط أول منتصف بالجذر الفعلي.","En":"Do not confuse the first midpoint with the exact root."},"FormulaLatex":"m=(a+b)/2","Substitution":{"Ar":"$m=(1+2)/2=1.5$","En":"$m=(1+2)/2=1.5$"},"Verification":{"Ar":"$m-1=2-m=0.5$","En":"$m-1=2-m=0.5$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":334,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"طريقة التنصيف تبدأ من منتصف المجال المعطى.","En":"Bisection begins at the midpoint of the given interval."},{"Ar":"اجمع طرفي المجال واقسم على اثنين؛ ويمكن فحص قيمة الدالة عند المنتصف.","En":"Average the endpoints; evaluate the function there if needed."}],"Solution":{"Idea":{"Ar":"طريقة التنصيف: منتصف فترة تحصر جذراً.","En":"Bisection: midpoint of a root bracket."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"الدالة مستمرة على الفترة وإشارتا قيمتي الطرفين مختلفتان، لذا تحصر جذراً.","En":"The function is continuous and endpoint values have opposite signs, so the interval brackets a root."},{"Ar":"$f(1)=-1,\\quad f(2)=2$","En":"$f(1)=-1,\\quad f(2)=2$"},{"Ar":"أول خطوة هي حساب متوسط الطرفين، وليس حل المعادلة بدقة.","En":"The first step averages the endpoints rather than solving exactly."}],"Result":{"Ar":"$1.5$","En":"$1.5$"},"CommonError":{"Ar":"لا تخلط أول منتصف بالجذر الفعلي.","En":"Do not confuse the first midpoint with the exact root."},"FormulaLatex":"m=(a+b)/2","Substitution":{"Ar":"$m=(1+2)/2=1.5$","En":"$m=(1+2)/2=1.5$"},"Verification":{"Ar":"$m-1=2-m=0.5$","En":"$m-1=2-m=0.5$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"1 هو الطرف الأيسر لا المنتصف.","En":"One is the left endpoint, not the midpoint."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"1.25 قد يظهر في خطوة لاحقة بعد تضييق الفترة.","En":"1.25 may occur in a later step after narrowing the bracket."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"2 هو الطرف الأيمن.","En":"Two is the right endpoint."},"Order":4}]}$mw$,$mw$طريقة التنصيف: منتصف فترة تحصر جذراً.

$m=(a+b)/2$

1. الدالة مستمرة على الفترة وإشارتا قيمتي الطرفين مختلفتان، لذا تحصر جذراً.

2. $f(1)=-1,\quad f(2)=2$

3. أول خطوة هي حساب متوسط الطرفين، وليس حل المعادلة بدقة.

$m=(1+2)/2=1.5$

$1.5$ لا توجد وحدة محددة في السؤال

$m-1=2-m=0.5$

لا تخلط أول منتصف بالجذر الفعلي.$mw$,$mw$Bisection: midpoint of a root bracket.

$m=(a+b)/2$

1. The function is continuous and endpoint values have opposite signs, so the interval brackets a root.

2. $f(1)=-1,\quad f(2)=2$

3. The first step averages the endpoints rather than solving exactly.

$m=(1+2)/2=1.5$

$1.5$ No unit specified

$m-1=2-m=0.5$

Do not confuse the first midpoint with the exact root.$mw$),
(868,1624,$mw$AEF111679D5A1E88D053359DAED3E67105B90CAE989A0FCC663EAE3178D09520$mw$,$mw$59197b285c25218add04d28ce0399f54$mw$,$mw$$mw$,$mw${"Id":1624,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"نبدأ التنصيف للدالة $f(x)=x^2-4$ على [1,3]. ما قيمة أول نقطة وسطية تحقق $f(x)=0$؟","TitleEn":"Start bisection for $f(x)=x^2-4$ on [1,3]. What first midpoint makes $f(x)=0$?","QuestionTextAr":"نبدأ التنصيف للدالة $f(x)=x^2-4$ على [1,3]. ما قيمة أول نقطة وسطية تحقق $f(x)=0$؟","QuestionTextEn":"Start bisection for $f(x)=x^2-4$ on [1,3]. What first midpoint makes $f(x)=0$?","DetailedSolutionAr":"القانون المستخدم: في طريقة التنصيف المنتصف الأول m = (a+b)/2. حدود الفترة [1،3]، لذلك m = (1+3)/2 = 2. نحسب الدالة f(2) = 2² − 4 = 0، وهكذا وجدنا جذراً دقيقاً من أول اختبار للمنتصف، ولا نحتاج متابعة التنصيف.","DetailedSolutionEn":"Rule used: The first bisection midpoint is m = (a+b)/2. On [1,3], m = (1+3)/2 = 2. Evaluate the function f(2) = 2² − 4 = 0. The first midpoint is already an exact root, so no further bisection is needed.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6485,"Order":1,"LatexCode":"2","IsCorrect":true},{"Id":6486,"Order":2,"LatexCode":"1.5","IsCorrect":false},{"Id":6487,"Order":3,"LatexCode":"3","IsCorrect":false},{"Id":6488,"Order":4,"LatexCode":"4","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"طريقة التنصيف تبدأ من منتصف المجال المعطى.","En":"Bisection begins at the midpoint of the given interval."},{"Ar":"اجمع طرفي المجال واقسم على اثنين؛ ويمكن فحص قيمة الدالة عند المنتصف.","En":"Average the endpoints; evaluate the function there if needed."}],"Title":{"Ar":"نبدأ التنصيف للدالة $f(x)=x^2-4$ على [1,3]. ما قيمة أول نقطة وسطية تحقق $f(x)=0$؟","En":"Start bisection for $f(x)=x^2-4$ on [1,3]. What first midpoint makes $f(x)=0$?"},"Points":10,"Options":[{"LatexCode":"2","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"1.5","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1.5 ليس منتصف الفترة ولا جذراً.","En":"1.5 is neither the interval midpoint nor a root."}},{"LatexCode":"3","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"3 هو الطرف الأيمن وقيمة الدالة عنده 5.","En":"Three is the right endpoint with function value five."}},{"LatexCode":"4","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"4 خارج الفترة وقيمة الدالة عنده 12.","En":"Four is outside the interval with function value twelve."}}],"StageId":4,"Question":{"Ar":"نبدأ التنصيف للدالة $f(x)=x^2-4$ على [1,3]. ما قيمة أول نقطة وسطية تحقق $f(x)=0$؟","En":"Start bisection for $f(x)=x^2-4$ on [1,3]. What first midpoint makes $f(x)=0$?"},"Solution":{"Idea":{"Ar":"نحسب منتصف الفترة ثم نفحص قيمة الدالة.","En":"Find the bracket midpoint, then evaluate the function."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"تضمن الاستمرارية واختلاف الإشارتين وجود جذر في الفترة.","En":"Continuity and opposite signs guarantee a root in the interval."},{"Ar":"$f(1)=-3,\\quad f(3)=5,\\quad m=(1+3)/2$","En":"$f(1)=-3,\\quad f(3)=5,\\quad m=(1+3)/2$"},{"Ar":"نحسب المنتصف ثم نفحص الدالة؛ قيمتها صفر تماماً فتتوقف الطريقة.","En":"Find the midpoint and evaluate; its function value is exactly zero, so the method stops."}],"Result":{"Ar":"$2$","En":"$2$"},"CommonError":{"Ar":"إذا كانت قيمة الدالة عند المنتصف صفراً فلا حاجة إلى تنصيف جديد.","En":"If the midpoint function value is zero, no further bisection is needed."},"FormulaLatex":"m=(a+b)/2","Substitution":{"Ar":"$m=2,\\quad f(2)=0$","En":"$m=2,\\quad f(2)=0$"},"Verification":{"Ar":"$2^2-4=0$","En":"$2^2-4=0$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":334,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"طريقة التنصيف تبدأ من منتصف المجال المعطى.","En":"Bisection begins at the midpoint of the given interval."},{"Ar":"اجمع طرفي المجال واقسم على اثنين؛ ويمكن فحص قيمة الدالة عند المنتصف.","En":"Average the endpoints; evaluate the function there if needed."}],"Solution":{"Idea":{"Ar":"نحسب منتصف الفترة ثم نفحص قيمة الدالة.","En":"Find the bracket midpoint, then evaluate the function."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"تضمن الاستمرارية واختلاف الإشارتين وجود جذر في الفترة.","En":"Continuity and opposite signs guarantee a root in the interval."},{"Ar":"$f(1)=-3,\\quad f(3)=5,\\quad m=(1+3)/2$","En":"$f(1)=-3,\\quad f(3)=5,\\quad m=(1+3)/2$"},{"Ar":"نحسب المنتصف ثم نفحص الدالة؛ قيمتها صفر تماماً فتتوقف الطريقة.","En":"Find the midpoint and evaluate; its function value is exactly zero, so the method stops."}],"Result":{"Ar":"$2$","En":"$2$"},"CommonError":{"Ar":"إذا كانت قيمة الدالة عند المنتصف صفراً فلا حاجة إلى تنصيف جديد.","En":"If the midpoint function value is zero, no further bisection is needed."},"FormulaLatex":"m=(a+b)/2","Substitution":{"Ar":"$m=2,\\quad f(2)=0$","En":"$m=2,\\quad f(2)=0$"},"Verification":{"Ar":"$2^2-4=0$","En":"$2^2-4=0$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"1.5 ليس منتصف الفترة ولا جذراً.","En":"1.5 is neither the interval midpoint nor a root."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"3 هو الطرف الأيمن وقيمة الدالة عنده 5.","En":"Three is the right endpoint with function value five."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"4 خارج الفترة وقيمة الدالة عنده 12.","En":"Four is outside the interval with function value twelve."},"Order":4}]}$mw$,$mw$نحسب منتصف الفترة ثم نفحص قيمة الدالة.

$m=(a+b)/2$

1. تضمن الاستمرارية واختلاف الإشارتين وجود جذر في الفترة.

2. $f(1)=-3,\quad f(3)=5,\quad m=(1+3)/2$

3. نحسب المنتصف ثم نفحص الدالة؛ قيمتها صفر تماماً فتتوقف الطريقة.

$m=2,\quad f(2)=0$

$2$ لا توجد وحدة محددة في السؤال

$2^2-4=0$

إذا كانت قيمة الدالة عند المنتصف صفراً فلا حاجة إلى تنصيف جديد.$mw$,$mw$Find the bracket midpoint, then evaluate the function.

$m=(a+b)/2$

1. Continuity and opposite signs guarantee a root in the interval.

2. $f(1)=-3,\quad f(3)=5,\quad m=(1+3)/2$

3. Find the midpoint and evaluate; its function value is exactly zero, so the method stops.

$m=2,\quad f(2)=0$

$2$ No unit specified

$2^2-4=0$

If the midpoint function value is zero, no further bisection is needed.$mw$),
(869,1625,$mw$85BF96FA7551B7B70A6E356A55FD13218193D1A3A3D998C1A07A19E42354FF6D$mw$,$mw$7f5ab6596ea1c9bdcf2ad531381ebed0$mw$,$mw$$mw$,$mw${"Id":1625,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"لدالة $f(x)=x^2-9$ مع $x_0=4$، ما قيمة $x_1$ بطريقة نيوتن؟","TitleEn":"For $f(x)=x^2-9$ with $x_0=4$, compute the first Newton iterate $x_1$.","QuestionTextAr":"لدالة $f(x)=x^2-9$ مع $x_0=4$، ما قيمة $x_1$ بطريقة نيوتن؟","QuestionTextEn":"For $f(x)=x^2-9$ with $x_0=4$, compute the first Newton iterate $x_1$.","DetailedSolutionAr":"القانون المستخدم: تكرار نيوتن لإيجاد جذر هو x₁ = x₀ − f(x₀)/f′(x₀). للدالة f(x)=x²−9 مشتقتها f′(x)=2x. عند x₀=4 نجد f(4)=16−9=7 وf′(4)=8. إذن x₁=4−7/8=25/8=3.125. المشتقة غير صفرية، لذا خطوة نيوتن معرفة.","DetailedSolutionEn":"Rule used: Newton's iteration is x₁ = x₀ − f(x₀)/f′(x₀). For f(x) = x² − 9, derivative f′(x) = 2x. At x₀ = 4, f(4) = 7 and f′(4) = 8. Therefore x₁ = 4 − 7/8 = 25/8 = 3.125.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6489,"Order":1,"LatexCode":"3.5","IsCorrect":false},{"Id":6490,"Order":2,"LatexCode":"3","IsCorrect":false},{"Id":6491,"Order":3,"LatexCode":"3.25","IsCorrect":false},{"Id":6492,"Order":4,"LatexCode":"3.125","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"طريقة نيوتن تحتاج قيمة الدالة ومشتقتها عند التخمين الحالي.","En":"Newton's method uses the function and derivative at the current guess."},{"Ar":"استخدم x₁=x₀−f(x₀)/f′(x₀) بعد حساب المشتقة.","En":"Use x₁=x₀−f(x₀)/f′(x₀) after finding the derivative."}],"Title":{"Ar":"لدالة $f(x)=x^2-9$ مع $x_0=4$، ما قيمة $x_1$ بطريقة نيوتن؟","En":"For $f(x)=x^2-9$ with $x_0=4$, compute the first Newton iterate $x_1$."},"Points":10,"Options":[{"LatexCode":"3.5","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"3.5 يطرح نصفاً بدلاً من 7/8.","En":"3.5 subtracts one half rather than 7/8."}},{"LatexCode":"3","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"3 هو الجذر الموجب الدقيق وليس أول تكرار لنيوتن.","En":"Three is the exact positive root, not the first Newton iterate."}},{"LatexCode":"3.25","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"3.25 يطرح 3/4 بدلاً من 7/8.","En":"3.25 subtracts 3/4 rather than 7/8."}},{"LatexCode":"3.125","IsCorrect":true,"ErrorType":"","Reason":null}],"StageId":4,"Question":{"Ar":"لدالة $f(x)=x^2-9$ مع $x_0=4$، ما قيمة $x_1$ بطريقة نيوتن؟","En":"For $f(x)=x^2-9$ with $x_0=4$, compute the first Newton iterate $x_1$."},"Solution":{"Idea":{"Ar":"خطوة نيوتن تستعمل قيمة الدالة ومشتقتها عند التخمين الحالي.","En":"Newton's step uses the function and derivative at the current iterate."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"مشتقة الدالة 2x، وقيمتها عند التخمين 4 تساوي 8، فلا تكون القسمة على صفر.","En":"The derivative is 2x, equal to eight at guess four, so division is valid."},{"Ar":"$f(4)=7,\\quad f'(4)=8$","En":"$f(4)=7,\\quad f'(4)=8$"},{"Ar":"نطرح من التخمين الحالي نسبة قيمة الدالة إلى مشتقتها؛ الناتج تقاطع المماس مع محور x.","En":"Subtract the function-to-derivative ratio; the result is the tangent's x-intercept."}],"Result":{"Ar":"$3.125$","En":"$3.125$"},"CommonError":{"Ar":"لا تعوض المشتقة عند الجذر المجهول؛ استعمل التخمين الحالي.","En":"Evaluate the derivative at the current guess, not the unknown root."},"FormulaLatex":"x_{n+1}=x_n-\\frac{f(x_n)}{f'(x_n)},\\quad f'(x_n)\\ne0","Substitution":{"Ar":"$x_1=4-7/8=25/8=3.125$","En":"$x_1=4-7/8=25/8=3.125$"},"Verification":{"Ar":"$7+8(25/8-4)=0$","En":"$7+8(25/8-4)=0$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":334,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"طريقة نيوتن تحتاج قيمة الدالة ومشتقتها عند التخمين الحالي.","En":"Newton's method uses the function and derivative at the current guess."},{"Ar":"استخدم x₁=x₀−f(x₀)/f′(x₀) بعد حساب المشتقة.","En":"Use x₁=x₀−f(x₀)/f′(x₀) after finding the derivative."}],"Solution":{"Idea":{"Ar":"خطوة نيوتن تستعمل قيمة الدالة ومشتقتها عند التخمين الحالي.","En":"Newton's step uses the function and derivative at the current iterate."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"مشتقة الدالة 2x، وقيمتها عند التخمين 4 تساوي 8، فلا تكون القسمة على صفر.","En":"The derivative is 2x, equal to eight at guess four, so division is valid."},{"Ar":"$f(4)=7,\\quad f'(4)=8$","En":"$f(4)=7,\\quad f'(4)=8$"},{"Ar":"نطرح من التخمين الحالي نسبة قيمة الدالة إلى مشتقتها؛ الناتج تقاطع المماس مع محور x.","En":"Subtract the function-to-derivative ratio; the result is the tangent's x-intercept."}],"Result":{"Ar":"$3.125$","En":"$3.125$"},"CommonError":{"Ar":"لا تعوض المشتقة عند الجذر المجهول؛ استعمل التخمين الحالي.","En":"Evaluate the derivative at the current guess, not the unknown root."},"FormulaLatex":"x_{n+1}=x_n-\\frac{f(x_n)}{f'(x_n)},\\quad f'(x_n)\\ne0","Substitution":{"Ar":"$x_1=4-7/8=25/8=3.125$","En":"$x_1=4-7/8=25/8=3.125$"},"Verification":{"Ar":"$7+8(25/8-4)=0$","En":"$7+8(25/8-4)=0$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"3.5 يطرح نصفاً بدلاً من 7/8.","En":"3.5 subtracts one half rather than 7/8."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"3 هو الجذر الموجب الدقيق وليس أول تكرار لنيوتن.","En":"Three is the exact positive root, not the first Newton iterate."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"3.25 يطرح 3/4 بدلاً من 7/8.","En":"3.25 subtracts 3/4 rather than 7/8."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$خطوة نيوتن تستعمل قيمة الدالة ومشتقتها عند التخمين الحالي.

$x_{n+1}=x_n-\frac{f(x_n)}{f'(x_n)},\quad f'(x_n)\ne0$

1. مشتقة الدالة 2x، وقيمتها عند التخمين 4 تساوي 8، فلا تكون القسمة على صفر.

2. $f(4)=7,\quad f'(4)=8$

3. نطرح من التخمين الحالي نسبة قيمة الدالة إلى مشتقتها؛ الناتج تقاطع المماس مع محور x.

$x_1=4-7/8=25/8=3.125$

$3.125$ لا توجد وحدة محددة في السؤال

$7+8(25/8-4)=0$

لا تعوض المشتقة عند الجذر المجهول؛ استعمل التخمين الحالي.$mw$,$mw$Newton's step uses the function and derivative at the current iterate.

$x_{n+1}=x_n-\frac{f(x_n)}{f'(x_n)},\quad f'(x_n)\ne0$

1. The derivative is 2x, equal to eight at guess four, so division is valid.

2. $f(4)=7,\quad f'(4)=8$

3. Subtract the function-to-derivative ratio; the result is the tangent's x-intercept.

$x_1=4-7/8=25/8=3.125$

$3.125$ No unit specified

$7+8(25/8-4)=0$

Evaluate the derivative at the current guess, not the unknown root.$mw$),
(870,1626,$mw$3DED942B371273A68423AC1103FCDDA8F8C492E9EE70772FF4F3EEA75D2F0F27$mw$,$mw$52888ab9c37a269ea81e8631fb72ae9f$mw$,$mw$$mw$,$mw${"Id":1626,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة شبه المنحرف باستخدام فترة واحدة.","TitleEn":"Approximate the integral of $f(x)=x^2$ from 0 to 2 by the trapezoidal rule using one panel.","QuestionTextAr":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة شبه المنحرف باستخدام فترة واحدة.","QuestionTextEn":"Approximate the integral of $f(x)=x^2$ from 0 to 2 by the trapezoidal rule using one panel.","DetailedSolutionAr":"القانون المستخدم: قاعدة شبه المنحرف بلوحة واحدة لتقريب التكامل هي T = (b−a)[f(a)+f(b)]/2. لدينا f(x)=x² وحدود التكامل a=0 وb=2. نحسب f(0)=0 وf(2)=4، ثم T=(2−0)(0+4)/2=4. هذه قيمة تقريبية، وليست التكامل الدقيق بالضرورة.","DetailedSolutionEn":"Rule used: The one-panel trapezoidal approximation is T = (b−a)[f(a)+f(b)]/2. For f(x) = x² on [0,2], f(0) = 0 and f(2) = 4. Thus T = (2−0)(0+4)/2 = 4. This is the rule's approximation, not necessarily the exact integral.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6493,"Order":1,"LatexCode":"4","IsCorrect":true},{"Id":6494,"Order":2,"LatexCode":"2","IsCorrect":false},{"Id":6495,"Order":3,"LatexCode":"\\frac83","IsCorrect":false},{"Id":6496,"Order":4,"LatexCode":"8","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"قاعدة شبه المنحرف بلوح واحد تستخدم قيمتي الدالة عند طرفي المجال.","En":"The one-panel trapezoidal rule uses both endpoint values."},{"Ar":"اضرب عرض المجال في متوسط قيمتي الدالة عند الطرفين.","En":"Multiply interval width by the average of the endpoint function values."}],"Title":{"Ar":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة شبه المنحرف باستخدام فترة واحدة.","En":"Approximate the integral of $f(x)=x^2$ from 0 to 2 by the trapezoidal rule using one panel."},"Points":10,"Options":[{"LatexCode":"4","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"2","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"2 ناتج قاعدة المنتصف بلوح واحد.","En":"Two is the one-panel midpoint estimate."}},{"LatexCode":"\\frac83","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"8/3 التكامل الدقيق لا تقدير شبه المنحرف.","En":"8/3 is the exact integral, not the trapezoid estimate."}},{"LatexCode":"8","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"8 يهمل القسمة على اثنين في متوسط الطرفين.","En":"Eight omits division by two in the endpoint average."}}],"StageId":4,"Question":{"Ar":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة شبه المنحرف باستخدام فترة واحدة.","En":"Approximate the integral of $f(x)=x^2$ from 0 to 2 by the trapezoidal rule using one panel."},"Solution":{"Idea":{"Ar":"قاعدة شبه المنحرف تستخدم متوسط قيمتي الطرفين في عرض الفترة.","En":"The trapezoidal rule multiplies the average endpoint value by interval width."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"الفترة الواحدة عرضها 2، وقيمتا الطرفين صفر وأربعة.","En":"The single panel has width two and endpoint heights zero and four."},{"Ar":"$f(0)=0,\\quad f(2)=4$","En":"$f(0)=0,\\quad f(2)=4$"},{"Ar":"نضرب عرض الفترة في متوسط ارتفاعي الطرفين، وهو اثنان.","En":"Multiply the interval width by the mean endpoint height, two."}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"لا تستخدم قيمة المنتصف بدلاً من قيم الطرفين في هذه القاعدة.","En":"Do not replace endpoint values with the midpoint value."},"FormulaLatex":"T=\\frac{b-a}{2}(f(a)+f(b))","Substitution":{"Ar":"$T=(2/2)(0+4)=4$","En":"$T=(2/2)(0+4)=4$"},"Verification":{"Ar":"$T> \\int_0^2x^2\\,dx=8/3$","En":"$T> \\int_0^2x^2\\,dx=8/3$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":333,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"قاعدة شبه المنحرف بلوح واحد تستخدم قيمتي الدالة عند طرفي المجال.","En":"The one-panel trapezoidal rule uses both endpoint values."},{"Ar":"اضرب عرض المجال في متوسط قيمتي الدالة عند الطرفين.","En":"Multiply interval width by the average of the endpoint function values."}],"Solution":{"Idea":{"Ar":"قاعدة شبه المنحرف تستخدم متوسط قيمتي الطرفين في عرض الفترة.","En":"The trapezoidal rule multiplies the average endpoint value by interval width."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"الفترة الواحدة عرضها 2، وقيمتا الطرفين صفر وأربعة.","En":"The single panel has width two and endpoint heights zero and four."},{"Ar":"$f(0)=0,\\quad f(2)=4$","En":"$f(0)=0,\\quad f(2)=4$"},{"Ar":"نضرب عرض الفترة في متوسط ارتفاعي الطرفين، وهو اثنان.","En":"Multiply the interval width by the mean endpoint height, two."}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"لا تستخدم قيمة المنتصف بدلاً من قيم الطرفين في هذه القاعدة.","En":"Do not replace endpoint values with the midpoint value."},"FormulaLatex":"T=\\frac{b-a}{2}(f(a)+f(b))","Substitution":{"Ar":"$T=(2/2)(0+4)=4$","En":"$T=(2/2)(0+4)=4$"},"Verification":{"Ar":"$T> \\int_0^2x^2\\,dx=8/3$","En":"$T> \\int_0^2x^2\\,dx=8/3$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"2 ناتج قاعدة المنتصف بلوح واحد.","En":"Two is the one-panel midpoint estimate."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"8/3 التكامل الدقيق لا تقدير شبه المنحرف.","En":"8/3 is the exact integral, not the trapezoid estimate."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"8 يهمل القسمة على اثنين في متوسط الطرفين.","En":"Eight omits division by two in the endpoint average."},"Order":4}]}$mw$,$mw$قاعدة شبه المنحرف تستخدم متوسط قيمتي الطرفين في عرض الفترة.

$T=\frac{b-a}{2}(f(a)+f(b))$

1. الفترة الواحدة عرضها 2، وقيمتا الطرفين صفر وأربعة.

2. $f(0)=0,\quad f(2)=4$

3. نضرب عرض الفترة في متوسط ارتفاعي الطرفين، وهو اثنان.

$T=(2/2)(0+4)=4$

$4$ لا توجد وحدة محددة في السؤال

$T> \int_0^2x^2\,dx=8/3$

لا تستخدم قيمة المنتصف بدلاً من قيم الطرفين في هذه القاعدة.$mw$,$mw$The trapezoidal rule multiplies the average endpoint value by interval width.

$T=\frac{b-a}{2}(f(a)+f(b))$

1. The single panel has width two and endpoint heights zero and four.

2. $f(0)=0,\quad f(2)=4$

3. Multiply the interval width by the mean endpoint height, two.

$T=(2/2)(0+4)=4$

$4$ No unit specified

$T> \int_0^2x^2\,dx=8/3$

Do not replace endpoint values with the midpoint value.$mw$),
(871,1627,$mw$6FB2B50A969686F3158E3C756E2E82D55406AF0176F04D74DA593B9A81365D0D$mw$,$mw$2040239c236013a1de44dbac2aafbf0e$mw$,$mw$$mw$,$mw${"Id":1627,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة المنتصف بفترة واحدة.","TitleEn":"Approximate the integral of $f(x)=x^2$ from 0 to 2 using the one-panel midpoint rule.","QuestionTextAr":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة المنتصف بفترة واحدة.","QuestionTextEn":"Approximate the integral of $f(x)=x^2$ from 0 to 2 using the one-panel midpoint rule.","DetailedSolutionAr":"القانون المستخدم: قاعدة المنتصف بلوحة واحدة تعطي M = (b−a) × f((a+b)/2). للدالة f(x)=x² على [0،2] نحسب المنتصف (0+2)/2=1، وقيمة الدالة f(1)=1. طول الفترة 2، لذلك M=2×1=2، وهي قيمة التقريب المطلوب.","DetailedSolutionEn":"Rule used: The single-panel midpoint rule is M = (b−a) f((a+b)/2). On [0,2], the midpoint is 1 and f(1) = 1² = 1. The interval width is 2, so M = 2 × 1 = 2.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6497,"Order":1,"LatexCode":"1","IsCorrect":false},{"Id":6498,"Order":2,"LatexCode":"2","IsCorrect":true},{"Id":6499,"Order":3,"LatexCode":"4","IsCorrect":false},{"Id":6500,"Order":4,"LatexCode":"\\frac83","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"قاعدة المنتصف تستخدم قيمة الدالة في منتصف المجال.","En":"The midpoint rule uses the function at the interval midpoint."},{"Ar":"احسب منتصف المجال ثم اضرب قيمة الدالة عنده في عرض المجال.","En":"Find the midpoint, then multiply its function value by interval width."}],"Title":{"Ar":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة المنتصف بفترة واحدة.","En":"Approximate the integral of $f(x)=x^2$ from 0 to 2 using the one-panel midpoint rule."},"Points":10,"Options":[{"LatexCode":"1","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1 هو ارتفاع المستطيل فقط دون ضربه في العرض.","En":"One is the rectangle height without its width."}},{"LatexCode":"2","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"4","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"4 ناتج شبه المنحرف بفترة واحدة.","En":"Four is the one-panel trapezoid result."}},{"LatexCode":"\\frac83","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"8/3 القيمة الدقيقة وليست تقدير المنتصف.","En":"8/3 is exact, not the midpoint estimate."}}],"StageId":4,"Question":{"Ar":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة المنتصف بفترة واحدة.","En":"Approximate the integral of $f(x)=x^2$ from 0 to 2 using the one-panel midpoint rule."},"Solution":{"Idea":{"Ar":"قاعدة المنتصف تستخدم ارتفاع الدالة عند منتصف الفترة.","En":"The midpoint rule uses the function height at the interval midpoint."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"نحسب منتصف الفترة [0,2] وهو 1.","En":"Find the midpoint of [0,2], which is one."},{"Ar":"$m=1,\\quad f(1)=1$","En":"$m=1,\\quad f(1)=1$"},{"Ar":"ارتفاع المستطيل التقريبي هو قيمة الدالة عند المنتصف، وعرضه اثنان.","En":"The approximating rectangle has midpoint height and width two."}],"Result":{"Ar":"$2$","En":"$2$"},"CommonError":{"Ar":"لا تهمل عرض الفترة عند ضرب الارتفاع.","En":"Do not omit the interval width."},"FormulaLatex":"M=(b-a)f((a+b)/2)","Substitution":{"Ar":"$M=2\\cdot1=2$","En":"$M=2\\cdot1=2$"},"Verification":{"Ar":"$M<\\int_0^2x^2\\,dx=8/3$","En":"$M<\\int_0^2x^2\\,dx=8/3$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":333,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"قاعدة المنتصف تستخدم قيمة الدالة في منتصف المجال.","En":"The midpoint rule uses the function at the interval midpoint."},{"Ar":"احسب منتصف المجال ثم اضرب قيمة الدالة عنده في عرض المجال.","En":"Find the midpoint, then multiply its function value by interval width."}],"Solution":{"Idea":{"Ar":"قاعدة المنتصف تستخدم ارتفاع الدالة عند منتصف الفترة.","En":"The midpoint rule uses the function height at the interval midpoint."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"نحسب منتصف الفترة [0,2] وهو 1.","En":"Find the midpoint of [0,2], which is one."},{"Ar":"$m=1,\\quad f(1)=1$","En":"$m=1,\\quad f(1)=1$"},{"Ar":"ارتفاع المستطيل التقريبي هو قيمة الدالة عند المنتصف، وعرضه اثنان.","En":"The approximating rectangle has midpoint height and width two."}],"Result":{"Ar":"$2$","En":"$2$"},"CommonError":{"Ar":"لا تهمل عرض الفترة عند ضرب الارتفاع.","En":"Do not omit the interval width."},"FormulaLatex":"M=(b-a)f((a+b)/2)","Substitution":{"Ar":"$M=2\\cdot1=2$","En":"$M=2\\cdot1=2$"},"Verification":{"Ar":"$M<\\int_0^2x^2\\,dx=8/3$","En":"$M<\\int_0^2x^2\\,dx=8/3$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"1 هو ارتفاع المستطيل فقط دون ضربه في العرض.","En":"One is the rectangle height without its width."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"4 ناتج شبه المنحرف بفترة واحدة.","En":"Four is the one-panel trapezoid result."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"8/3 القيمة الدقيقة وليست تقدير المنتصف.","En":"8/3 is exact, not the midpoint estimate."},"Order":4}]}$mw$,$mw$قاعدة المنتصف تستخدم ارتفاع الدالة عند منتصف الفترة.

$M=(b-a)f((a+b)/2)$

1. نحسب منتصف الفترة [0,2] وهو 1.

2. $m=1,\quad f(1)=1$

3. ارتفاع المستطيل التقريبي هو قيمة الدالة عند المنتصف، وعرضه اثنان.

$M=2\cdot1=2$

$2$ لا توجد وحدة محددة في السؤال

$M<\int_0^2x^2\,dx=8/3$

لا تهمل عرض الفترة عند ضرب الارتفاع.$mw$,$mw$The midpoint rule uses the function height at the interval midpoint.

$M=(b-a)f((a+b)/2)$

1. Find the midpoint of [0,2], which is one.

2. $m=1,\quad f(1)=1$

3. The approximating rectangle has midpoint height and width two.

$M=2\cdot1=2$

$2$ No unit specified

$M<\int_0^2x^2\,dx=8/3$

Do not omit the interval width.$mw$),
(872,1628,$mw$64F89C25C3A8120C7847F2C02C710386B99091B7EA3479890E1E319398156C76$mw$,$mw$ae2ca00acf160478809f1a739cb34402$mw$,$mw$$mw$,$mw${"Id":1628,"StageId":4,"CategoryId":90,"Points":10,"TitleAr":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة سمبسون 1/3 باستخدام فترتين فرعيتين متساويتين.","TitleEn":"Use Simpson's 1/3 rule with two equal subintervals to integrate $f(x)=x^2$ from 0 to 2.","QuestionTextAr":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة سمبسون 1/3 باستخدام فترتين فرعيتين متساويتين.","QuestionTextEn":"Use Simpson's 1/3 rule with two equal subintervals to integrate $f(x)=x^2$ from 0 to 2.","DetailedSolutionAr":"القانون المستخدم: قاعدة سيمبسون 1/3 لفترتين متساويتين تستخدم S = h/3[f(x₀)+4f(x₁)+f(x₂)]، حيث h=(b−a)/2. على [0،2] يكون h=1 والنقاط 0 و1 و2، وقيم الدالة x² هي 0 و1 و4. بالتعويض S=(1/3)(0+4×1+4)=8/3، وهي دقيقة هنا لأن الدالة تربيعية.","DetailedSolutionEn":"Rule used: Simpson's 1/3 rule with two equal subintervals is S = h/3[f(x₀)+4f(x₁)+f(x₂)], h=(b−a)/2. For [0,2], h = 1 and f(0)=0, f(1)=1, f(2)=4. Hence S = (1/3)(0+4×1+4) = 8/3, exact for a quadratic.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6501,"Order":1,"LatexCode":"4","IsCorrect":false},{"Id":6502,"Order":2,"LatexCode":"2","IsCorrect":false},{"Id":6503,"Order":3,"LatexCode":"\\frac43","IsCorrect":false},{"Id":6504,"Order":4,"LatexCode":"\\frac{8}{3}","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"قسّم المجال إلى جزأين متساويين وحدّد h.","En":"Split the interval into two equal subintervals and find h."},{"Ar":"استخدم قاعدة سمبسون h/3 مضروباً في مجموع قيم الدالة بأوزان 1 و4 و1.","En":"Use Simpson's rule: h/3 times the weighted sum with weights 1, 4, 1."}],"Title":{"Ar":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة سمبسون 1/3 باستخدام فترتين فرعيتين متساويتين.","En":"Use Simpson's 1/3 rule with two equal subintervals to integrate $f(x)=x^2$ from 0 to 2."},"Points":10,"Options":[{"LatexCode":"4","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"4 هو تقدير شبه المنحرف الواحد.","En":"Four is the one-panel trapezoid estimate."}},{"LatexCode":"2","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"2 هو تقدير المنتصف الواحد.","En":"Two is the one-panel midpoint estimate."}},{"LatexCode":"\\frac43","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"4/3 يهمل إحدى مساهمتي 4 في المجموع الموزون.","En":"4/3 omits one of the contributions of four in the weighted sum."}},{"LatexCode":"\\frac{8}{3}","IsCorrect":true,"ErrorType":"","Reason":null}],"StageId":4,"Question":{"Ar":"قدّر التكامل من 0 إلى 2 للدالة $f(x)=x^2$ بقاعدة سمبسون 1/3 باستخدام فترتين فرعيتين متساويتين.","En":"Use Simpson's 1/3 rule with two equal subintervals to integrate $f(x)=x^2$ from 0 to 2."},"Solution":{"Idea":{"Ar":"قاعدة سمبسون تستخدم الأوزان 1، 4، 1 على فترتين متساويتين.","En":"Simpson's rule uses weights 1, 4, 1 on two equal subintervals."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"نقسم الفترة إلى فترتين متساويتين؛ طول كل منهما واحد.","En":"Split the interval into two equal subintervals, each of length one."},{"Ar":"$h=1,\\quad(f(0),f(1),f(2))=(0,1,4)$","En":"$h=1,\\quad(f(0),f(1),f(2))=(0,1,4)$"},{"Ar":"نضرب قيم الدالة بالأوزان 1 و4 و1، ثم نضرب المجموع في h/3.","En":"Weight the function values by one, four and one, then multiply the sum by h/3."}],"Result":{"Ar":"$\\frac{8}{3}$","En":"$\\frac{8}{3}$"},"CommonError":{"Ar":"لا تستخدم عرض الفترة الكلي مكان طول الفترة الفرعية h.","En":"Do not use the total interval width in place of subinterval width h."},"FormulaLatex":"S=\\frac h3(f(a)+4f(a+h)+f(b)),\\quad h=(b-a)/2","Substitution":{"Ar":"$S=(0+4+4)/3=8/3$","En":"$S=(0+4+4)/3=8/3$"},"Verification":{"Ar":"$\\int_0^2x^2\\,dx=[x^3/3]_0^2=8/3$","En":"$\\int_0^2x^2\\,dx=[x^3/3]_0^2=8/3$"}},"TrackIds":[18,21],"CategoryId":90,"PrimarySkillId":333,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"قسّم المجال إلى جزأين متساويين وحدّد h.","En":"Split the interval into two equal subintervals and find h."},{"Ar":"استخدم قاعدة سمبسون h/3 مضروباً في مجموع قيم الدالة بأوزان 1 و4 و1.","En":"Use Simpson's rule: h/3 times the weighted sum with weights 1, 4, 1."}],"Solution":{"Idea":{"Ar":"قاعدة سمبسون تستخدم الأوزان 1، 4، 1 على فترتين متساويتين.","En":"Simpson's rule uses weights 1, 4, 1 on two equal subintervals."},"Unit":{"Ar":"لا توجد وحدة محددة في السؤال","En":"No unit specified"},"Steps":[{"Ar":"نقسم الفترة إلى فترتين متساويتين؛ طول كل منهما واحد.","En":"Split the interval into two equal subintervals, each of length one."},{"Ar":"$h=1,\\quad(f(0),f(1),f(2))=(0,1,4)$","En":"$h=1,\\quad(f(0),f(1),f(2))=(0,1,4)$"},{"Ar":"نضرب قيم الدالة بالأوزان 1 و4 و1، ثم نضرب المجموع في h/3.","En":"Weight the function values by one, four and one, then multiply the sum by h/3."}],"Result":{"Ar":"$\\frac{8}{3}$","En":"$\\frac{8}{3}$"},"CommonError":{"Ar":"لا تستخدم عرض الفترة الكلي مكان طول الفترة الفرعية h.","En":"Do not use the total interval width in place of subinterval width h."},"FormulaLatex":"S=\\frac h3(f(a)+4f(a+h)+f(b)),\\quad h=(b-a)/2","Substitution":{"Ar":"$S=(0+4+4)/3=8/3$","En":"$S=(0+4+4)/3=8/3$"},"Verification":{"Ar":"$\\int_0^2x^2\\,dx=[x^3/3]_0^2=8/3$","En":"$\\int_0^2x^2\\,dx=[x^3/3]_0^2=8/3$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"4 هو تقدير شبه المنحرف الواحد.","En":"Four is the one-panel trapezoid estimate."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"2 هو تقدير المنتصف الواحد.","En":"Two is the one-panel midpoint estimate."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"4/3 يهمل إحدى مساهمتي 4 في المجموع الموزون.","En":"4/3 omits one of the contributions of four in the weighted sum."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$قاعدة سمبسون تستخدم الأوزان 1، 4، 1 على فترتين متساويتين.

$S=\frac h3(f(a)+4f(a+h)+f(b)),\quad h=(b-a)/2$

1. نقسم الفترة إلى فترتين متساويتين؛ طول كل منهما واحد.

2. $h=1,\quad(f(0),f(1),f(2))=(0,1,4)$

3. نضرب قيم الدالة بالأوزان 1 و4 و1، ثم نضرب المجموع في h/3.

$S=(0+4+4)/3=8/3$

$\frac{8}{3}$ لا توجد وحدة محددة في السؤال

$\int_0^2x^2\,dx=[x^3/3]_0^2=8/3$

لا تستخدم عرض الفترة الكلي مكان طول الفترة الفرعية h.$mw$,$mw$Simpson's rule uses weights 1, 4, 1 on two equal subintervals.

$S=\frac h3(f(a)+4f(a+h)+f(b)),\quad h=(b-a)/2$

1. Split the interval into two equal subintervals, each of length one.

2. $h=1,\quad(f(0),f(1),f(2))=(0,1,4)$

3. Weight the function values by one, four and one, then multiply the sum by h/3.

$S=(0+4+4)/3=8/3$

$\frac{8}{3}$ No unit specified

$\int_0^2x^2\,dx=[x^3/3]_0^2=8/3$

Do not use the total interval width in place of subinterval width h.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
